CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,username TEXT UNIQUE,password TEXT,role TEXT DEFAULT 'citizen',phone TEXT,house_no TEXT,address TEXT);
CREATE TABLE IF NOT EXISTS complaints(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,category TEXT,description TEXT,status TEXT DEFAULT 'Pending',created TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS taxes(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,type TEXT,amount REAL,year TEXT,status TEXT DEFAULT 'Pending',mode TEXT,paid_on TIMESTAMP,receipt_no TEXT,verified INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS certificates(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,type TEXT,details TEXT,status TEXT DEFAULT 'Pending',created TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content(id INTEGER PRIMARY KEY AUTOINCREMENT,section TEXT,title TEXT,body TEXT,created TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
